class Solution {
    const int MOD = 1e9 + 7;

    long modPow(long x, long n) {
        long res = 1;
        while (n) {
            if (n % 2) res = res * x % MOD;
            x = x * x % MOD;
            n /= 2;
        }
        return res;
    }

public:
    int countGoodNumbers(long n) {
        return modPow(5, (n + 1) / 2) * modPow(4, n / 2) % MOD;
    }
};
